SELECT *
FROM customer behavior;

-- what is the total revenue generated by male vs female customers
SELECT gender,SUM(purchase_amount) as revenue 
FROM customer
GROUP BY gender;

-- which customers used a discount but still spent more than the average purchase amount
SELECT customer_id,purchase_amount
FROM customer
WHERE discount_applied ='Yes' and purchase_amount >= (SELECT AVG(purchase_amount)FROM customer);

-- Which are the top 5 products with the highest average review rating 
SELECT item_purchased,ROUND(AVG (review_rating::numeric),2) as "average product rating"
FROM customer
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC
limit 5;

-- compare the average purchase amounts between standard and express shipping 
SELECT shipping_type,ROUND(AVG(purchase_amount),2)
FROM customer
WHERE shipping_type in ('Standard','Express')
GROUP BY shipping_type ;

-- Do subscrbied customers spend more?compare average spend and total revenue between subscribers and non-subscribers
SELECT subscription_status,
COUNT(customer_id)as total_customers,
ROUND (AVG(purchase_amount),2) as avg_spend,
SUM (purchase_amount) as total_revenue
FROM customer
GROUP BY subscription_status
Order by total_revenue,avg_spend DESC;

--what 5 products have the biggest percentage of purchases with discounts applied
SELECT item_purchased,
ROUND(
	100* SUM(CASE 
		WHEN discount_applied ='Yes' THEN 1 
			ELSE 0
			END) /COUNT(*) ,2
		)as discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate desc
limit 5;

-- segement customers into new,returning and loyal based on their total number of previous purchases and show the count of each segment 
WITH customer_type AS(
SELECT customer_id,previous_purchases,
CASE 
	WHEN previous_purchases=1 THEN 'New'
	WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
	ELSE 'Loyal'
	END AS customer_segment
FROM customer 	
)

SELECT customer_segment,count(*) AS number_of_customers
from customer_type
GROUP BY customer_segment;

-- What are the top 3 most purchased products within category ?
WITH item_counts AS(
SELECT category,
item_purchased,
COUNT(customer_id) as total_orders,
Row_number() over(
	partition by category 
		order by count(customer_id) desc)as item_rank
FROM customer
GROUP BY category,item_purchased
)
SELECT item_rank,category,item_purchased,total_orders
FROM item_counts
WHERE item_rank <=3;
-- are customers who are repeated buyers(more than 5 previous purchases) also likely to subscribe?
SELECT subscription_status,
COUNT(customer_id) as repeat_buyers
FROM customer
WHERE previous_purchases>5
GROUP BY subscription_status;

-- What is the revenue contribution of each age group?
SELECT age_group,
SUM(purchase_amount) as total_revenue
FROM customer
GROUP BY age_group
ORDER BY total_revenue DESC;